PAGE = r"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Cyber Twin | Safety Tools</title>
<style>body{font:16px system-ui;max-width:750px;margin:40px auto;padding:0 18px;color:#202434;background:#f7f6fb}section{background:white;padding:24px;border-radius:14px;margin:20px 0}textarea,input,button{font:inherit;box-sizing:border-box;width:100%;padding:12px;border:1px solid #bbb;border-radius:8px}textarea{min-height:125px}button{background:#493396;color:white;border:0;margin-top:12px;cursor:pointer}output{display:block;white-space:pre-wrap;line-height:1.6;margin-top:12px}</style>
<h1>Cyber Twin safety tools</h1>
<section><h2>Module 3: Phishing message checker</h2><p>Paste a suspicious message to see possible warning signs. Links are never opened.</p><textarea id="message" maxlength="10000" placeholder="Paste a message here"></textarea><button id="scan">Check message</button><output id="message-result" aria-live="polite"></output></section>
<section><h2>Module 4: Password strength checker</h2><p>Try a made-up example password. The check runs on the server and does not store your input.</p><input id="password" type="password" maxlength="256" autocomplete="off" placeholder="Enter a sample password"><button id="check-password">Check strength</button><output id="password-result" aria-live="polite"></output><small>This is a pattern check, not a leaked-password check.</small></section>
<script>
async function run(endpoint,field,inputId,resultId,format){const input=document.getElementById(inputId),out=document.getElementById(resultId);if(!input.value.trim()){out.textContent='Enter something to check.';return}out.textContent='Checking…';try{const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({[field]:input.value})});if(!res.ok)throw new Error('Unable to check this input.');out.textContent=format(await res.json())}catch(e){out.textContent=e.message}finally{if(field==='password')input.value=''}}
document.getElementById('scan').onclick=()=>run('/tools/phishing/check','message','message','message-result',d=>'Result: '+d.risk_level+'\n'+(d.warning_signs.map(x=>'• '+x.sign+' — '+x.advice).join('\n')||'No obvious warning signs found.')+'\n'+d.note);
document.getElementById('check-password').onclick=()=>run('/tools/password/check','password','password','password-result',d=>'Rating: '+d.rating+' ('+d.score+'/100)\n'+d.suggestions.map(x=>'• '+x).join('\n')+'\n'+d.note);
</script></html>"""
